#!/usr/bin/env python3
"""P38-12: generates docs/evidence/p38/SCANNER_COMPARISON.md from committed results (h4-main matrix, p36 checkov run). `--check` compares to the committed file."""
import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); OUT = os.path.join(ROOT, "docs", "evidence", "p38", "SCANNER_COMPARISON.md")
def build():
    h = json.load(open(os.path.join(ROOT, "results/v2/h4-main/result.json")))["aggregate"]; p36 = json.load(open(os.path.join(ROOT, "results/v2/p36-checkov-compare/result.json"))); mx = h["scenario_matrix"]
    def cnt(prefix, b): return sum(1 for s, v in mx[b].items() if s.startswith(prefix) and v == ".") , sum(1 for s, v in mx[b].items() if s.startswith(prefix) and v != "-")
    L = ["# P38-12 comparison with mature scanners — incremental-novelty verdict", "", "_Generated by `scripts/p38_compare.py`. CANDIDATE. Read the verdict column with the caveats beneath it._", "",
         "| Class | Mature-scanner stand-in | Stand-in stops | Horizon layer | Horizon stops | Verdict on incremental novelty |", "|---|---|---|---|---|---|"]
    a, n = cnt("HCCB", "B3"); c, m = cnt("HCCB", "B4"); L.append(f"| Generated-code defects (HCCB) | B3 = **real bandit** + secret scan | {a}/{n} | codegate (B4) | {c}/{m} | **Partly supported.** The gain comes from the dynamic exploit oracle and permit-bound release, not from better static detection; 1 type (HCCB-06) is stopped by no baseline |")
    a, n = cnt("HIEB", "B3"); c, m = cnt("HIEB", "B7"); L.append(f"| Infra exposure (HIEB) | B3 = **emulation** of 3 literal patterns | {a}/{n} | InfraGuard in B7 | {c}/{m} | **Not demonstrated against real tools.** Emulated B3 is weak by construction; real checkov could not parse the fixtures (below) |")
    L.append(f"| Infra exposure, real tool (P36) | checkov {p36['checkov_version']} | {p36['checkov_detected']}/{p36['n_bad']} detected, {p36['checkov_unsupported_format']} unsupported-format | InfraGuard | {p36['infraguard_detected']}/{p36['n_bad']} | **Rejected as a breadth claim; inconclusive as a depth claim.** The fixtures use InfraGuard's own annotated format, which favours InfraGuard; checkov covers far more |")
    for pre, name in (("HMIB", "Model artifact integrity"), ("HECB", "Cross-agent channels and forensic integrity")):
        a, n = cnt(pre, "B3"); c, m = cnt(pre, "B7"); L.append(f"| {name} ({pre}) | scanners (B3) | {a}/{n} | intake/isolation/telemetry (B7) | {c}/{m} | **Supported for this synthetic set, with no like-for-like scanner to beat.** Mature SAST/CSPM tools do not examine these artifacts, so the comparison is 'covered vs not covered by that tool class', not 'better than' |")
    L += ["", "## Caveats that decide how much the table can carry", "* The suites were written around the layers' threat classes, so Horizon coverage is by construction high. A scanner losing here says the scanner was not built for that class.", "* `B3` for HIEB is a three-pattern emulation. Do not cite it as evidence about checkov, Trivy, Prowler or any CSPM product.", f"* Checkov caveats from P36: {'; '.join(p36['caveats'][:3])}.", "* HMIB has **no unsafe-serialization (pickle-style) scenario**, the one model-artifact class that model-file scanners do cover; the 0/16 for scanners reflects that omission as much as any weakness of scanners.", "* Nothing here measures false-positive rates on large real corpora.", "", "## Verdict", "Incremental novelty is **supported only** for (a) release control that binds an exploit-oracle result to a signed permit and (b) classes with no mature-scanner counterpart (model provenance, cross-agent channels, receiver-anchored forensics), and **only on synthetic fixtures**. It is **not supported** for infrastructure-posture detection, where the one real-tool comparison was format-limited and inconclusive, and the breadth of mature CSPM tools is far greater.", ""]
    return "\n".join(L)
if __name__ == "__main__":
    t = build()
    if "--check" in sys.argv: ok = open(OUT).read() == t; print("p38 scanner comparison:", "MATCH" if ok else "MISMATCH"); sys.exit(0 if ok else 1)
    open(OUT, "w").write(t); print("wrote", OUT)
